118	                  "w-64!",
119	                  "[&_.leaflet-popup-content-wrapper]:rounded-lg",
120	                  "[&_.leaflet-popup-content-wrapper]:border",
121	                  "[&_.leaflet-popup-content-wrapper]:border-border",
122	                  "[&_.leaflet-popup-content-wrapper]:bg-background",
